-- 5-Question Canary Insert for jee-pyq-master
INSERT OR IGNORE INTO questions (question_id, exam_name, year, session, shift, subject, question_number, question_type, question_text, options, correct_answer, source_sha256) VALUES ('JM2025_MATH_001', 'JEE Main', 2025, 'January', 'JEE Main 2025 (22 Jan Shift 1)', 'Mathematics', 1, 'MCQ', 'Let $a_1, a_2, a_3, \ldots$ be a G.P. of increasing terms. If $a_1 a_5 = 28$ and $a_2 + a_4 = 29$, then $a_6$ is equal to:', '[{"key": "A", "label": "1", "text": "628"}, {"key": "B", "label": "2", "text": "812"}, {"key": "C", "label": "3", "text": "526"}, {"key": "D", "label": "4", "text": "784"}]', '4', '1febdee8664f11bf7e934a42181de01e45870e789dcb25100c610bf39899db36');
INSERT OR IGNORE INTO questions (question_id, exam_name, year, session, shift, subject, question_number, question_type, question_text, options, correct_answer, source_sha256) VALUES ('JM2025_MATH_002', 'JEE Main', 2025, 'January', 'JEE Main 2025 (22 Jan Shift 1)', 'Mathematics', 2, 'MCQ', 'Let $x = x(y)$ be the solution of the differential equation $y^2 \, dx + (x - \frac{1}{y}) \, dy = 0$. If $x(1) = 1$, then $x \left( \frac{1}{3} \right)$ is:', '[{"key": "A", "label": "1", "text": "$\\frac{1}{3} + e$"}, {"key": "B", "label": "2", "text": "$3 + e$"}, {"key": "C", "label": "3", "text": "$3 - e$"}, {"key": "D", "label": "4", "text": "$\\frac{3}{2} + e$"}]', '3', '1febdee8664f11bf7e934a42181de01e45870e789dcb25100c610bf39899db36');
INSERT OR IGNORE INTO questions (question_id, exam_name, year, session, shift, subject, question_number, question_type, question_text, options, correct_answer, source_sha256) VALUES ('JM2025_MATH_003', 'JEE Main', 2025, 'January', 'JEE Main 2025 (22 Jan Shift 1)', 'Mathematics', 3, 'MCQ', 'Two balls are selected at random one by one without replacement from a bag containing 4 white and 6 black balls. If the probability that the first selected ball is black, given that the second selected ball is also black, is $\frac{m}{n}$, where $\gcd(m, n) = 1$, then $m + n$ is equal to:', '[{"key": "A", "label": "1", "text": "4"}, {"key": "B", "label": "2", "text": "14"}, {"key": "C", "label": "3", "text": "13"}, {"key": "D", "label": "4", "text": "11"}]', '2', '1febdee8664f11bf7e934a42181de01e45870e789dcb25100c610bf39899db36');
INSERT OR IGNORE INTO questions (question_id, exam_name, year, session, shift, subject, question_number, question_type, question_text, options, correct_answer, source_sha256) VALUES ('JM2025_MATH_004', 'JEE Main', 2025, 'January', 'JEE Main 2025 (22 Jan Shift 1)', 'Mathematics', 4, 'MCQ', 'The product of all solutions of the equation $e^{5 \log x^2 + 3} = x^8, x > 0$, is:', '[{"key": "A", "label": "1", "text": "$e^{8/5}$"}, {"key": "B", "label": "2", "text": "$e^{6/5}$"}, {"key": "C", "label": "3", "text": "$e^{2}$"}, {"key": "D", "label": "4", "text": "$e$"}]', '1', '1febdee8664f11bf7e934a42181de01e45870e789dcb25100c610bf39899db36');
INSERT OR IGNORE INTO questions (question_id, exam_name, year, session, shift, subject, question_number, question_type, question_text, options, correct_answer, source_sha256) VALUES ('JM2025_MATH_005', 'JEE Main', 2025, 'January', 'JEE Main 2025 (22 Jan Shift 1)', 'Mathematics', 5, 'MCQ', 'Let the triangle PQR be the image of the triangle with vertices $(1, 3), (3, 1)$ and $(2, 4)$ in the line $x + 2y = 2$. If the centroid of $\triangle PQR$ is the point $(\alpha, \beta)$, then $15(\alpha - \beta)$ is equal to:', '[{"key": "A", "label": "1", "text": "19"}, {"key": "B", "label": "2", "text": "24"}, {"key": "C", "label": "3", "text": "21"}, {"key": "D", "label": "4", "text": "22"}]', '4', '1febdee8664f11bf7e934a42181de01e45870e789dcb25100c610bf39899db36');